document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));$('#new-run').onclick=()=>runModal();refresh();setInterval(()=>{if(!$('#dialog').open)refresh();},1500);

function updateSurfaceAccess(){const narrow=window.matchMedia('(max-width: 1000px)').matches,drawer=window.matchMedia('(max-width: 760px)').matches&&!$('#assistant-panel').hidden,menu=document.body.classList.contains('nav-open');$('#sidebar').inert=drawer||(narrow&&!menu);$('#workspace').inert=drawer||(narrow&&menu);if(narrow&&!menu)$('#sidebar').setAttribute('aria-hidden','true');else $('#sidebar').removeAttribute('aria-hidden');}
function closeNavigation(){document.body.classList.remove('nav-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#nav-backdrop').hidden=true;updateSurfaceAccess();}
function openAssistant(context={}){assistantReturnFocus=document.activeElement;assistantContext=context;$('#assistant-panel').hidden=false;const mobile=window.matchMedia('(max-width: 760px)').matches;$('#assistant-panel').setAttribute('role',mobile?'dialog':'complementary');if(mobile)$('#assistant-panel').setAttribute('aria-modal','true');else $('#assistant-panel').removeAttribute('aria-modal');$('#workspace').inert=mobile;$('#sidebar').inert=mobile;document.body.classList.add('assistant-open');$('#assistant-toggle').setAttribute('aria-expanded','true');$('#assistant-backdrop').hidden=!window.matchMedia('(max-width: 760px)').matches;renderAssistant();updateSurfaceAccess();$('#assistant-close').focus();}
function closeAssistant(){$('#workspace').inert=false;$('#sidebar').inert=false;document.body.classList.remove('assistant-open');$('#assistant-panel').hidden=true;$('#assistant-backdrop').hidden=true;$('#assistant-toggle').setAttribute('aria-expanded','false');updateSurfaceAccess();if(assistantReturnFocus?.isConnected)assistantReturnFocus.focus();else if(window.matchMedia('(max-width: 1000px)').matches)$('#content').focus({preventScroll:true});else $('#assistant-toggle').focus();}
function renderAssistant(){
 if($('#assistant-panel').hidden)return;
 const r=assistantContext.runId?(selected?.id===assistantContext.runId?selected:runData(state.runs.find(x=>x.id===assistantContext.runId)||{id:assistantContext.runId})):selected;
 const b=state.boards.find(x=>x.id===(assistantContext.boardId||r?.board_id||chosenBoard))||r?.board_snapshot;
 const s=assistantContext.scriptId?state.scripts.find(x=>x.id===assistantContext.scriptId):r?.script_snapshot;
 const lines=r?.events?.slice(-5).map(x=>'['+x.level+'] '+x.message).join('\n');
 const html=`<div class="assistant-status"><span class="pill neutral">Assistant not configured</span></div><p class="assistant-intro">Explain errors, draft scripts and plan debugging.</p><section class="context-card"><h3>Selected context <span aria-hidden="true">${icon('more',18)}</span></h3><dl><div><dt>Board</dt><dd>${esc(b?.name||'No board selected')}</dd></div><div><dt>Run</dt><dd>${r?.plan?esc(testName(r)+' · '+(r.outcome||r.state)):'No run selected'}</dd></div><div><dt>Connection</dt><dd>${esc(r?.plan?transportLabel(usedTransport(r)):b?transportLabel(boardConnection(b).via||'Not confirmed'):'Not selected')}</dd></div><div><dt>Context</dt><dd><span class="context-tag">${r?'Run logs':'Board settings'}</span>${s?`<span class="context-tag">Script v${esc(s.version||1)}</span>`:''}</dd></div></dl><details data-key="assistant-context"><summary>Review shared context</summary>${s?`<p>${esc(s.name)} · v${esc(s.version||1)} · SHA ${esc(s.sha256)}</p>`:''}${b?`<p>Policy: ${esc(automaticPolicy(b))}</p>${b.connection_checks?.ssh?.error?`<p>SSH: ${esc(b.connection_checks.ssh.error)}</p>`:''}`:''}${lines?`<pre>${esc(lines)}</pre>`:'<p class="muted">No run logs selected. Open a result to choose its evidence.</p>'}${r?.failure?failureInfo(r.failure):''}${r?.cycles?.at(-1)?.kernel_log?`<pre>${esc(r.cycles.at(-1).kernel_log)}</pre>`:''}</details></section><p class="context-privacy">${icon('info',17)} Context stays local. No model is connected.</p><h3 class="assistant-question">What would you like help with?</h3><button class="assistant-action" disabled>${icon('file',25)}<span><strong>Explain this error</strong><small>Evidence and next checks</small></span>${icon('chevron',19)}</button><button class="assistant-action" disabled>${icon('code',25)}<span><strong>Draft a test script</strong><small>Review before running</small></span>${icon('chevron',19)}</button><button class="assistant-action" disabled>${icon('search',25)}<span><strong>Suggest debugging steps</strong><small>Prioritized checks</small></span>${icon('chevron',19)}</button><div class="assistant-config"><button class="primary" disabled>${icon('gear',20)} Configure assistant</button><p>Model setup and generation are not available yet.</p></div><div class="assistant-compose"><label class="sr-only" for="assistant-prompt">Ask about selected context</label><textarea id="assistant-prompt" disabled placeholder="Ask about the selected board or run…" rows="2"></textarea><span aria-hidden="true">${icon('send',20)}</span></div><p class="assistant-safety">${icon('shield',18)} Scripts are never run automatically.</p><p class="sr-only">Future workflow: Draft → Review/Edit → Save → Run. No AI answers are simulated.</p>`;

 const el=$('#assistant-content'),fresh=el.cloneNode(false);fresh.innerHTML=html;syncElement(el,fresh);
}
async function checkPolicy(bid){
 const b=state.boards.find(x=>x.id===bid);if(!b||connectionPending.has(bid))return;
 try{
  if(b.mode==='simulator'){await api('boards/'+bid+'/verify',{transport:'simulator'});notify('Simulator checked; no physical hardware contacted.');return;}
  if(b.host&&b.username){
   connectionPending.set(bid,'Checking SSH');render();
   try{await api('boards/'+bid+'/verify',{transport:'ssh'});notify('Ready via SSH.');return;}
   catch(e){
    if(/host key|fingerprint|known_hosts/i.test(e.message)){notify('SSH host trust requires review: '+e.message);return;}
    if(!b.serial_port){notify('SSH failed: '+e.message+'. UART is not configured.');return;}
   }
  }else if(!b.serial_port){notify('Configure SSH or UART before checking this board.');return;}
  connectionPending.set(bid,'Connecting UART');render();await api('boards/'+bid+'/verify',{transport:'uart'});notify('Ready via UART. Review the recorded SSH check in connection details.');
 }catch(e){notify('Connection check failed: '+e.message);}
 finally{connectionPending.delete(bid);await refresh();}
}
function bindWorkspace(){
 if($('#board-search'))$('#board-search').oninput=e=>{boardSearch=e.target.value;render();};
 if($('#board-filter'))$('#board-filter').onchange=e=>{boardFilter=e.target.value;render();};
 if($('#results-filter'))$('#results-filter').onchange=e=>{resultsFilter=e.target.value;render();};
 document.querySelectorAll('[data-check-policy]').forEach(b=>b.onclick=()=>checkPolicy(b.dataset.checkPolicy));
 document.querySelectorAll('[data-select-board]').forEach(b=>b.onclick=()=>{chosenBoard=b.dataset.selectBoard;assistantContext={boardId:chosenBoard};render();});
 document.querySelectorAll('[data-assist]').forEach(b=>b.onclick=async()=>{
  const context={intent:b.dataset.assist,boardId:b.dataset.boardId,runId:b.dataset.runId||selected?.id,scriptId:b.dataset.scriptId};
  if(context.runId){try{detailsCache.set(context.runId,await api('runs/'+context.runId));}catch(e){notify(e.message);}}
  openAssistant(context);
 });
 document.querySelectorAll('[data-cancel-run]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('runs/'+b.dataset.cancelRun+'/control',{action:'stop'});notify('Cancellation requested. Already issued actions cannot be undone.');await refresh();}catch(e){notify(e.message);b.disabled=false;}});
}
