$('#assistant-close').onclick=closeAssistant;$('#assistant-backdrop').onclick=closeAssistant;
$('#menu-toggle').onclick=()=>{const open=!document.body.classList.contains('nav-open');document.body.classList.toggle('nav-open',open);$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#nav-backdrop').hidden=!open;updateSurfaceAccess();if(open)$('#sidebar [data-nav]').focus();};
$('#close-menu').onclick=()=>{closeNavigation();$('#menu-toggle').focus();};$('#nav-backdrop').onclick=closeNavigation;
window.addEventListener('resize',()=>{const mobile=window.matchMedia('(max-width: 760px)').matches;const open=!$('#assistant-panel').hidden;$('#workspace').inert=open&&mobile;$('#sidebar').inert=open&&mobile;if(open){$('#assistant-panel').setAttribute('role',mobile?'dialog':'complementary');if(mobile)$('#assistant-panel').setAttribute('aria-modal','true');else $('#assistant-panel').removeAttribute('aria-modal');}$('#assistant-backdrop').hidden=$('#assistant-panel').hidden||!window.matchMedia('(max-width: 760px)').matches;if(window.matchMedia('(min-width: 1001px)').matches)closeNavigation();updateSurfaceAccess();});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'){if($('#dialog').open)return;if(!$('#assistant-panel').hidden)closeAssistant();if(document.body.classList.contains('nav-open')){closeNavigation();$('#menu-toggle').focus();}document.querySelectorAll('.board-options[open]').forEach(x=>x.open=false);}
 if(e.key==='Tab'){
  const region=!$('#assistant-panel').hidden&&window.matchMedia('(max-width: 760px)').matches?$('#assistant-panel'):document.body.classList.contains('nav-open')?$('#sidebar'):null;
  if(!region||$('#dialog').open)return;
  const items=[...region.querySelectorAll('button:not(:disabled),summary,input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')].filter(x=>!x.closest('[hidden]'));
  if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}
 }
});
